// 나쁨: 불가능한 조합이 타입상 허용된다
interface State { loading: boolean; data?: Data; error?: Error }
//   loading + error 동시? data 있는데 loading? → 화면이 다 방어

// 좋음: 판별 유니온 — 유효한 상태만 표현 가능
type State =
  | { status: 'loading' }
  | { status: 'ok'; data: Data }
  | { status: 'error'; error: Error };
//   switch(state.status) 로 빠짐없이(exhaustive) 안전하게 분기

import { z } from 'zod';
const Item = z.object({
  id: z.string(),
  price: z.number().int().nonnegative(),
});
type Item = z.infer<typeof Item>;   // 스키마에서 타입 자동 도출

const item = Item.parse(await res.json());  // 모양 다르면 여기서 실패
//   as Item (거짓 약속) 대신 parse (진짜 검증)
//   통과 후에는 item 을 타입대로 안전하게 사용

